const row = $('Schleife: je N Seiten gleichzeitig').item.json;
const quick = $('Stufe 2: Schnellcheck (HTTP)').item.json;
const r = $json;

// Hinweis: Im n8n-Code-Knoten gibt es kein "new URL(...)".
// Deshalb zerlegen wir Adressen mit einem regulären Ausdruck selbst.
function zerlegeUrl(roh) {
  const m = String(roh || '').trim().match(/^(https?):\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  if (!m) return null;
  return { protokoll: m[1].toLowerCase(), host: m[2].toLowerCase(), pfad: m[3] || '/', query: m[4] || '' };
}

// Macht aus einer relativen Weiterleitung ("/karriere") eine volle Adresse.
function absoluteUrl(ziel, basis) {
  if (/^https?:\/\//i.test(ziel)) return ziel;
  const b = zerlegeUrl(basis);
  if (!b) return ziel;
  if (ziel.startsWith('//')) return b.protokoll + ':' + ziel;
  if (ziel.startsWith('/')) return b.protokoll + '://' + b.host + ziel;
  return b.protokoll + '://' + b.host + b.pfad.replace(/[^\/]*$/, '') + ziel;
}

// Zeigt eine Adresse nur noch auf eine allgemeine Karriere- oder Startseite?
function istAllgemeineSeite(ziel, original) {
  const z = zerlegeUrl(ziel);
  const o = zerlegeUrl(original);
  if (!z || !o) return false;
  const pfad = (u) => u.pfad.replace(/\/+$/, '').toLowerCase();
  const host = (u) => u.host.replace(/^www\./, '');
  if (host(z) === host(o) && pfad(z) === pfad(o)) return false; // z. B. nur http -> https
  const p = pfad(z);
  if (p === '') return true;
  if (/^(\/[a-z]{2}(-[a-z]{2})?)?(\/(karriere|career|careers|jobs|job|stellenangebote|stellen|offene-stellen|jobboerse|join-us|joinus|vacancies|work-with-us|search|suche))*$/.test(p)) return true;
  if (/[?&](error|expired|notfound|jobnotfound)=/i.test(z.query)) return true;
  return false;
}

const out = {
  id: row.id,
  http_status: r.httpStatus === undefined ? quick.statusCode || null : r.httpStatus,
  final_url: r.finalUrl || '',
  cache_id: r.cacheId || '',
  screenshot: r.screenshotUrl || '',
  text_hash: r.textHash || '',
  abgerufen_am: r.abgerufenAm || new Date().toISOString(),
};
const fehlerText = (x) => (x ? (typeof x === 'string' ? x : x.message || JSON.stringify(x)) : '');
const qCode = quick.statusCode || null;
const qLoc = quick.headers && (quick.headers.location || quick.headers.Location);

if (/ENOTFOUND|EAI_AGAIN|getaddrinfo/i.test(fehlerText(quick.error))) {
  out.status = 'tot';
  out.hinweis = 'Domain existiert nicht (mehr)';
} else if (qCode === 404 || qCode === 410) {
  out.status = 'tot';
  out.hinweis = `HTTP ${qCode}: Seite gibt es nicht mehr`;
} else if (qCode >= 300 && qCode < 400 && qLoc && istAllgemeineSeite(absoluteUrl(qLoc, row.url), row.url)) {
  out.status = 'tot';
  out.hinweis = `Weiterleitung auf allgemeine Seite: ${absoluteUrl(qLoc, row.url)}`;
} else if (!r.ok) {
  out.status = 'fehler';
  out.hinweis = 'Abruf fehlgeschlagen: ' + (fehlerText(r.error) || 'unbekannt');
} else if (r.httpStatus === 404 || r.httpStatus === 410) {
  out.status = 'tot';
  out.hinweis = `HTTP ${r.httpStatus}`;
} else if (istAllgemeineSeite(r.finalUrl, row.url)) {
  out.status = 'tot';
  out.hinweis = `Weitergeleitet auf allgemeine Seite: ${r.finalUrl}`;
} else if (r.blocked && r.blocked.any) {
  out.status = 'wartet_auf_freigabe';
  out.hinweis = 'Freigabe nötig: ' + (r.blocked.reasons || []).join(', ');
} else if ((r.textLength || 0) < 200) {
  out.status = 'fehler';
  out.hinweis = 'Seite enthält kaum Text';
} else {
  out.status = 'abgerufen';
  out.hinweis = 'Seite gespeichert – KI-Auswertung folgt (A2)';
}
return { json: out };

const z = {};
for (const i of $input.all()) z[i.json.status || 'unbekannt'] = (z[i.json.status || 'unbekannt'] || 0) + 1;
return [{ json: { abgerufen: $input.all().length, nach_status: z, naechster_schritt: 'Workflow "A2 Fakten auslesen" starten (braucht die GPU).' } }];
